-- city_data: 2024. évi lakónépesség (KSH + TEIR)
-- =============================================================================
--
-- Források:
--   • nepesseg_varosonkent.xlsx — országos települések (kód + lakónépesség)
--   • budapest_kerulet_nepesseg_2024_teir.xlsx — Budapest 01.–23. kerület
--     (TEIR: 2024 BP állandó népesség, dec. 31.) → I. kerület … XXIII. kerület
--
-- Importált települések: 3176
-- Kihagyva (nincs city_data.name): 1
--   • Budapest (összesen, KSH lakónépesség): nincs külön sor — helyette I.–XXIII. kerület (TEIR)
--   • Kétvölgy (90 fő): Nincs ilyen nevű sor a city_data táblában.
--
-- Generálva: tools/generate_city_data_population_sql.py
-- =============================================================================

ALTER TABLE public.city_data
  ADD COLUMN IF NOT EXISTS population_2024 bigint,
  ADD COLUMN IF NOT EXISTS panel_adatok TEXT,
  ADD COLUMN IF NOT EXISTS panel_rovid_szoveg TEXT,
  ADD COLUMN IF NOT EXISTS panel_leiras TEXT;

COMMENT ON COLUMN public.city_data.population_2024 IS
  'Lakónépesség 2024. dec. 31. (fő); BP kerületek: TEIR állandó népesség.';
COMMENT ON COLUMN public.city_data.panel_adatok IS
  'Találat panel: rövid adatsorok (soronként egy sor, pl. lakosság).';

UPDATE public.city_data AS c
SET
  population_2024 = v.pop,
  panel_adatok = CASE
    WHEN NULLIF(btrim(c.panel_adatok), '') IS NULL THEN v.panel_line
    WHEN c.panel_adatok ~ '^Lakosság \(2024\.' THEN
      regexp_replace(c.panel_adatok, '^Lakosság \(2024\.[^\n]*', v.panel_line)
    ELSE v.panel_line || E'\n' || c.panel_adatok
  END
FROM (VALUES
  ('Aba', 4371, 'Lakosság (2024. dec. 31.): 4 371 fő'),
